        {
            Debug.LogError("Data file not found: " + dataPath);
            return;
        }
        string jsonData = File.ReadAllText(dataPath);
        JArray data = JArray.Parse(jsonData);

        // 2. Create the Chart GameObject and Canvas
        GameObject chartObj = new GameObject("ElectricityConsumptionChart");

        // Position the chart 2 meters in front of the user
        // User is at (0, 1.7, 0) looking at (0, 0, -1)
        Vector3 chartPosition = new Vector3(0f, 1.50f, -2.00f);
        chartObj.transform.position = chartPosition;

        // Rotate to face the user (user is at Z=0, chart is at Z=-2, so chart forward should be +Z)
        chartObj.transform.rotation = Quaternion.LookRotation(new Vector3(0, 0, 1));
        chartObj.transform.localScale = new Vector3(0.002f, 0.002f, 0.002f);

        Canvas canvas = chartObj.AddComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        chartObj.AddComponent<CanvasScaler>();
        chartObj.AddComponent<GraphicRaycaster>();

        RectTransform rectTransform = chartObj.GetComponent<RectTransform>();
        rectTransform.sizeDelta = new Vector2(800f, 500f);

        // 3. Setup the Line Chart
        LineChart chart = chartObj.AddComponent<LineChart>();
        chart.Init();

        // Set Title
        var title = chart.GetOrAddChartComponent<Title>();
        title.text = "Electricity Consumption Over Time";
        title.subText = "Building 001 Utility Data";

        // Setup Axes
        var xAxis = chart.GetOrAddChartComponent<XAxis>();
        xAxis.type = Axis.AxisType.Category;
        xAxis.boundaryGap = true;

        var yAxis = chart.GetOrAddChartComponent<YAxis>();
        yAxis.type = Axis.AxisType.Value;

        // Add Legend
        var legend = chart.GetOrAddChartComponent<Legend>();
        legend.show = true;

        // 4. Populate Data
        chart.RemoveData();
        var serie = chart.AddSerie<Line>("Electricity (kWh)");

        // Set line color using the required hex format
        Color serieColor;
        if (ColorUtility.TryParseHtmlString("#5470C6FF", out serieColor))
        {
            serie.lineStyle.color = serieColor;
        }

        foreach (var item in data)
        {
            string timeLabel = item["time"].ToString();
            float electricityValue = item["electricity"].Value<float>();

            chart.AddXAxisData(timeLabel);
            chart.AddData(0, electricityValue);
        }

        // Optional: Smooth the line for better visualization
        serie.smooth = true;
        serie.symbol.show = false; // Hide dots for a cleaner look if there are many points
    }
}
